from collections import deque

def maximumDetonation(bombs):
    n = len(bombs)
    adj = [[] for _ in range(n)]

    # Build the graph: directed edges for reachability
    for i in range(n):
        x1, y1, r1 = bombs[i]
        for j in range(n):
            if i == j:
                continue
            x2, y2, _ = bombs[j]
            dx = x1 - x2
            dy = y1 - y2
            if dx * dx + dy * dy <= r1 * r1:
                adj[i].append(j)

    def bfs(start):
        visited = set([start])
        q = deque([start])
        while q:
            curr = q.popleft()
            for nb in adj[curr]:
                if nb not in visited:
                    visited.add(nb)
                    q.append(nb)
        return len(visited)

    result = 0
    for i in range(n):
        # try detonating from every bomb
        result = max(result, bfs(i))
    return result
